const defaultContent = (filename: string) => {
  if (filename.endsWith(".py")) {
    return `# Python starter
def main():
    print("Hello from CoFlux!")

if __name__ == "__main__":
    main()
`;
  }
  if (filename.endsWith(".c")) {
    return `#include <stdio.h>

int main() {
    printf("Hello from CoFlux!\\n");
    return 0;
}
`;
  }
  if (filename.endsWith(".java")) {
    return `public class Main {
    public static void main(String[] args) {
        System.out.println("Hello from CoFlux!");
    }
}
`;
  }
  if (filename.endsWith(".ts") || filename.endsWith(".tsx")) {
    return `import { Router } from "express";
import { auth } from "./middleware";

// Real-time collaborative session initialised
const router = Router();

router.use(auth);

router.get("/health", (req, res) => {
  return res.status(200).send({ status: "up" });
});

export default router;
`;
  }
  if (filename.endsWith(".sql")) {
    return `-- SQL Schema
CREATE TABLE users (
  id INT PRIMARY KEY AUTO_INCREMENT,
  name VARCHAR(255) NOT NULL,
  email VARCHAR(255) UNIQUE NOT NULL,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
`;
  }
  return `# ${filename.replace(/\..+$/, "")}

Welcome to your CoFlux workspace. Start editing here!
`;
};

