// Commit = save snapshot
const handleCommit = async (msg: string, andPush: boolean) => {
  if (!msg.trim()) { show("Commit message is required", "error"); return; }
  show(`Saving snapshot…`, "info");
  try {
    const res = await fetch(`http://localhost:1234/api/workspaces/${workspaceId}/snapshots`, {
      method: "POST",
      headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
      body: JSON.stringify({ label: msg, note: msg })
    });
    if (res.ok) {
      const snap = await res.json();
      setVersionHistory(prev => [snap, ...prev]);
      setTabs(prev => prev.map(t => ({ ...t, dirty: false })));
      show(`✓ Snapshot saved: "${msg}"`, "success");
      if (andPush) handlePush();
    } else {
      show("Failed to save snapshot", "error");
    }
  } catch { show("Error saving snapshot", "error"); }
};

