// Resolve comment via API
const resolveComment = async (id: string) => {
  try {
    await fetch(`http://localhost:1234/api/workspaces/${workspaceId}/comments/${id}/resolve`, {
      method: "PUT", headers: { Authorization: `Bearer ${token}` }
    });
    setComments(prev => prev.map(c => c.id === id ? { ...c, resolved: true } : c));
    show("Comment resolved", "success");
  } catch { show("Error resolving comment", "error"); }
};

// Reply to comment via API
const replyToComment = async (id: string, text: string) => {
  try {
    const res = await fetch(`http://localhost:1234/api/workspaces/${workspaceId}/comments/${id}/replies`, {
      method: "POST",
      headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
      body: JSON.stringify({ text })
    });
    if (res.ok) {
      const reply = await res.json();
      setComments(prev => prev.map(c => c.id === id ? { ...c, replies: [...(c.replies ?? []), reply] } : c));
      show("Reply added", "success");
    }
  } catch { show("Error adding reply", "error"); }
};

// Restore snapshot via API
const restoreVersion = async (snap: any) => {
  show(`Restoring "${snap.label}"…`, "info");
  try {
    const res = await fetch(`http://localhost:1234/api/workspaces/${workspaceId}/snapshots/${snap.id}/restore`, {
      method: "POST", headers: { Authorization: `Bearer ${token}` }
    });
    if (res.ok) {
      show(`✓ Restored to "${snap.label}" — reload to see changes`, "success");
    } else show("Failed to restore", "error");
  } catch { show("Error restoring snapshot", "error"); }
};

