function GithubModal({ token, onClose, onConnected, onToast }: { token: string; onClose: () => void; onConnected: () => void; onToast: (msg: string, type?: "success" | "error" | "info") => void }) {
  const [pat, setPat] = useState("");
  const [loading, setLoading] = useState(false);

  const handleConnect = async () => {
    if (!pat) return;
    setLoading(true);
    try {
      const res = await fetch("http://localhost:1234/api/github/connect", {
        method: "POST", headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
        body: JSON.stringify({ pat })
      });
      const data = await res.json();
      if (res.ok) {
        onConnected();
        onToast(`Connected as @${data.githubUsername}`, "success");
        onClose();
      } else {
        onToast(data.error || "Failed to connect", "error");
      }
    } catch { onToast("Error connecting to GitHub", "error"); }
    setLoading(false);
  };

  return (
    <div className="fixed inset-0 z-40 flex items-center justify-center bg-black/60 backdrop-blur-sm">
      <div className="w-full max-w-sm rounded-xl border border-zinc-700 bg-surface p-6 shadow-2xl">
        <div className="mb-4 flex items-center justify-between">
          <h2 className="text-sm font-semibold text-zinc-100">Connect GitHub</h2>
          <button onClick={onClose} className="text-zinc-500 hover:text-zinc-200"><X className="size-4" /></button>
        </div>
        <p className="mb-4 text-xs text-zinc-400">
          Enter a GitHub Personal Access Token (PAT) with `repo` scope to push code to GitHub.
        </p>
        <input
          autoFocus
          value={pat}
          onChange={(e) => setPat(e.target.value)}
          placeholder="ghp_xxxxxxxxxxxxxxxxxxxx"
          type="password"
          className="mb-4 h-9 w-full rounded-md border border-zinc-700 bg-panel px-3 text-xs text-zinc-100 placeholder:text-zinc-500 focus:border-brand focus:outline-none"
          onKeyDown={(e) => e.key === "Enter" && pat && handleConnect()}
        />
        <button
          disabled={loading || !pat}
          onClick={handleConnect}
          className="inline-flex w-full items-center justify-center gap-1.5 rounded-md bg-brand py-2 text-xs font-medium text-brand-foreground hover:brightness-110 disabled:opacity-50"
        >
          {loading ? "Connecting…" : "Connect Account"}
        </button>
      </div>
    </div>
  );
}

