const loadWorkspace = useCallback(() => {
  if (token && workspaceId) {
    fetch(`http://localhost:1234/api/workspaces/${workspaceId}`, {
      headers: { Authorization: `Bearer ${token}` }
    })
    .then(res => {
      if (!res.ok) {
        if (res.status === 404 || res.status === 401 || res.status === 403) navigate({ to: "/dashboard" });
        return null;
      }
      return res.json();
    })
    .then(data => {
      if (data) {
        setWorkspace(data);

        if (data.files && data.files.length > 0) {
          const buildTree = (paths: string[]): FileNode[] => {
            const root: FileNode[] = [];
            for (const path of paths) {
              const parts = path.split("/");
              let currentLevel = root;
              for (let i = 0; i < parts.length; i++) {
                const part = parts[i];
                const isFile = i === parts.length - 1;
                const existingNode = currentLevel.find(n => n.name === part);
                if (existingNode) {
                  if (!isFile) currentLevel = existingNode.children!;
                } else {
                  const id = parts.slice(0, i + 1).join("/");
                  if (isFile) {
                    const lang = part.endsWith(".md") ? "Markdown" : part.endsWith(".json") ? "JSON" : "JavaScript";
                    currentLevel.push({ id, name: part, type: "file", language: lang });
                  } else {
                    const newNode: FileNode = { id, name: part, type: "folder", children: [] };
                    currentLevel.push(newNode);
                    currentLevel = newNode.children!;
                  }
                }
              }
            }
            return root;
          };

          const newTree = buildTree(data.files);
          setTree(newTree);

          // Only update tabs if they're empty
          setTabs(prev => {
            if (prev.length > 0) return prev;
            const firstFile = data.files[0];
            const lang = firstFile.endsWith(".md") ? "Markdown" : "JavaScript";
            return [{ id: firstFile, name: firstFile.split("/").pop() || firstFile, kind: lang === "Markdown" ? "docs" : "code" }];
          });
          setActive(prev => prev === "" ? data.files[0] : prev);
        } else {
          setTree(prev => prev.length === 0 ? initialTree : prev);
          setTabs(prev => prev.length === 0 ? initialTabs : prev);
          setActive(prev => prev === "" ? initialTabs[0]?.id || "" : prev);
        }
      }
    })
    .catch(console.error);

    // Fetch comments
    fetch(`http://localhost:1234/api/workspaces/${workspaceId}/comments`, {
      headers: { Authorization: `Bearer ${token}` }
    }).then(r => r.json()).then(data => {
      setComments(data.map((c: any) => ({
        id: c.id,
        file: c.filename || "unknown",
        line: c.lineNumber || 1,
        resolved: c.resolved,
        author: {
          name: c.authorName,
          color: c.authorColor,
          initials: c.authorName ? c.authorName.split(" ").map((n: string) => n[0]).join("").slice(0, 2).toUpperCase() : "??"
        },
        when: new Date(c.createdAt).toLocaleDateString(),
        body: c.text,
        replies: c.replies
      })));
    }).catch(console.error);

    // Fetch version history
    fetch(`http://localhost:1234/api/workspaces/${workspaceId}/snapshots`, {
      headers: { Authorization: `Bearer ${token}` }
    }).then(r => r.json()).then(data => {
      setVersionHistory(data.map((s: any) => ({
        id: s.id,
        label: s.label,
        author: s.authorName,
        when: new Date(s.createdAt).toLocaleDateString(),
        note: s.note,
        files: s.files
      })));
    }).catch(console.error);
  }
}, [token, workspaceId, navigate]);

