function ChatPanel({ onToast, workspaceId, token, members }: { onToast: (msg: string, type?: "success" | "error" | "info") => void; workspaceId: string; token: string; members: any[] }) {
  const [draft, setDraft] = useState("");
  const [chatMessages, setChatMessages] = useState<any[]>([]);
  const [showEmojiPicker, setShowEmojiPicker] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const EMOJIS = ["👍", "❤️", "🔥", "✅", "🚀", "😄", "🎉", "👀", "💡", "⚠️"];

  const loadChat = useCallback(() => {
    fetch(`http://localhost:1234/api/workspaces/${workspaceId}/chat`, { headers: { Authorization: `Bearer ${token}` } })
      .then(res => res.json())
      .then(data => setChatMessages(data))
      .catch(console.error);
  }, [workspaceId, token]);

  useEffect(() => {
    loadChat();
    const interval = setInterval(loadChat, 5000); // Polling for now
    return () => clearInterval(interval);
  }, [loadChat]);

  const sendMessage = async () => {
    if (!draft.trim()) return;
    try {
      const res = await fetch(`http://localhost:1234/api/workspaces/${workspaceId}/chat`, {
        method: "POST", headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
        body: JSON.stringify({ text: draft.trim() })
      });
      if (res.ok) {
        const msg = await res.json();
        setChatMessages(prev => [...prev, msg]);
        setDraft("");
        setTimeout(() => messagesEndRef.current?.scrollIntoView({ behavior: "smooth" }), 50);
      }
    } catch { onToast("Error sending message", "error"); }
  };

  const handleAttach = () => {
    fileInputRef.current?.click();
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      onToast(`Attached: ${file.name}`, "success");
      // Could upload to a bucket, for now just a text message
      setDraft(prev => prev + ` [Attachment: ${file.name}]`);
    }
    e.target.value = "";
  };

