function CodeEditor({ 
  filename, 
  workspaceId,
  onCommentsChange,
  onRequestComment
}: { 
  filename: string; 
  workspaceId: string;
  onCommentsChange?: (comments: CommentData[]) => void;
  onRequestComment?: (pos: { start: Uint8Array, end: Uint8Array }) => void;
}) {
  const { user } = useAuth();

  const language = filename.endsWith(".ts") || filename.endsWith(".tsx") ? "typescript"
    : filename.endsWith(".js") || filename.endsWith(".jsx") ? "javascript"
    : filename.endsWith(".py") ? "python"
    : filename.endsWith(".c") || filename.endsWith(".h") ? "c"
    : filename.endsWith(".java") ? "java"
    : filename.endsWith(".sql") ? "sql"
    : filename.endsWith(".json") ? "json"
    : filename.endsWith(".html") ? "html"
    : filename.endsWith(".css") ? "css"
    : filename.endsWith(".md") ? "markdown"
    : "plaintext";

  const { doc, provider } = useMemo(() => getWorkspaceDoc(workspaceId, filename, user), [workspaceId, filename, user]);
  const ytext = useMemo(() => doc.getText(filename), [doc, filename]);
  const ycomments = useMemo(() => doc.getMap<CommentData>("comments"), [doc]);

  const editorRef = useRef<any>(null);
  const decorationsRef = useRef<any>(null);

  // Sync comments to parent state
  useEffect(() => {
    const updateParent = () => {
      if (onCommentsChange) {
        onCommentsChange(Array.from(ycomments.values()));
      }
    };
    ycomments.observe(updateParent);
    updateParent();
    return () => ycomments.unobserve(updateParent);
  }, [ycomments, onCommentsChange]);

  // Update Monaco decorations based on comments
  useEffect(() => {
    if (!editorRef.current || !decorationsRef.current) return;

    const updateDecorations = () => {
      const editor = editorRef.current;
      const model = editor.getModel();
      if (!model) return;

      const newDecorations: any[] = [];
      ycomments.forEach((c) => {
        if (c.resolved || !c.startPos || !c.endPos) return;

        try {
          const startAbs = Y.createAbsolutePositionFromRelativePosition(Y.decodeRelativePosition(c.startPos), doc);
          const endAbs = Y.createAbsolutePositionFromRelativePosition(Y.decodeRelativePosition(c.endPos), doc);

          if (startAbs && endAbs) {
            const start = model.getPositionAt(startAbs.index);
            const end = model.getPositionAt(endAbs.index);
            newDecorations.push({
              range: new monaco.Range(start.lineNumber, start.column, end.lineNumber, end.column),
              options: {
                className: "bg-yellow-500/30 cursor-pointer",
                hoverMessage: { value: `**${c.author.name}**: ${c.content}` },
              }
            });
          }
        } catch (e) {
          console.error("Failed to map comment decoration", e);
        }
      });
      decorationsRef.current.set(newDecorations);
    };

    ycomments.observe(updateDecorations);
    ytext.observe(updateDecorations);
    updateDecorations();

    return () => {
      ycomments.unobserve(updateDecorations);
      ytext.observe(updateDecorations);
    };
  }, [ycomments, ytext, doc]);

  // Initialize with default content if empty
  useEffect(() => {
    if (ytext.toString().length === 0) {
      ytext.insert(0, defaultContent(filename));
    }
  }, [ytext, filename]);

  const handleEditorMount = (editor: any, monaco: any) => {
    editorRef.current = editor;
    decorationsRef.current = editor.createDecorationsCollection();

    new MonacoBinding(ytext, editor.getModel(), new Set([editor]), provider.awareness);

    editor.addAction({
      id: "add-comment",
      label: "Add Comment",
      contextMenuGroupId: "navigation",
      contextMenuOrder: 1.5,
      run: (ed: any) => {
        const selection = ed.getSelection();
        if (selection && !selection.isEmpty()) {
          const model = ed.getModel();
          const startOffset = model.getOffsetAt(selection.getStartPosition());
          const endOffset = model.getOffsetAt(selection.getEndPosition());

          const startRel = Y.createRelativePositionFromTypeIndex(ytext, startOffset);
          const endRel = Y.createRelativePositionFromTypeIndex(ytext, endOffset);

          if (onRequestComment) {
            onRequestComment({
              start: Y.encodeRelativePosition(startRel),
              end: Y.encodeRelativePosition(endRel)
            });
          }
        }
      }
    });
  };

  return (

